<?php if($ceoDetailProject>0): ?><section class="ceo-v2-card"><h3>비용항목별 예측</h3><div class="ceo-v2-scroll"><table class="ceo-v2-table"><thead><tr><th>비용항목</th><th>현재</th><th>입력완료율</th><th>미입력 예상</th><th>최종 예상</th><th>범위</th><th>신뢰도</th><th>평균 입력지연</th><th>가능성</th></tr></thead><tbody><?php foreach($ceoCategoryRows as $row): ?><tr><td><?php echo h(isset($ceoCategoryLabels[$row['cost_type']])?$ceoCategoryLabels[$row['cost_type']]:$row['cost_type']); ?></td><td><?php echo h(cpms_ceo_v2_money($row['current_input_amount'])); ?></td><td><?php echo h(cpms_ceo_v2_rate($row['expected_completion_rate'])); ?></td><td><?php echo h(cpms_ceo_v2_money($row['expected_unentered_amount'])); ?></td><td><?php echo h(cpms_ceo_v2_money($row['final_forecast_amount'])); ?></td><td><?php echo h(cpms_ceo_v2_money($row['forecast_low_amount'])); ?> ~ <?php echo h(cpms_ceo_v2_money($row['forecast_high_amount'])); ?></td><td><?php echo h(cpms_ceo_v2_score($row['forecast_confidence_score'])); ?></td><td><?php echo h($row['average_input_lag_days']===null?'-':number_format((float)$row['average_input_lag_days'],1).'일'); ?></td><td>과다 <?php echo h($row['overinput_grade']); ?> / 미입력 <?php echo h($row['missing_possibility_grade']); ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
